<?php
session_start();
require_once '../middleware/teacher.php';
require_once '../config/database.php';
require_once '../helpers/csrf_helper.php';
require_once '../helpers/teacher_document_helper.php';
$documentId=(int)($_GET['document']??0);
$document=getTeacherDocumentForReview($pdo,(int)$_SESSION['user_id'],$documentId);
if(!$document){renderApplicationAlert('ไม่พบเอกสารหรือไม่มีสิทธิ์ตรวจสอบ', 'requests.php', 404);}
$fromCoordinator=(($_GET['from']??'')==='coordinator'&&strtoupper((string)$document['document_code'])==='INTERNSHIP_INFO'&&str_contains((string)($document['workflow_step_name']??''),'อาจารย์ประสานงาน'));
$returnPage=$fromCoordinator?'coordinator_requests.php':'requests.php';
if(!in_array($document['document_status'],['submitted','in_review'],true)){header('Location: '.$returnPage.'?notice=not-pending');exit;}
$teacher=$document['teacher'];$teacher_name=trim($teacher['firstname'].' '.$teacher['lastname']);$pending_document_count=0;$pageHeading='พิจารณาคำร้อง '.$document['document_code'];
$reviewStmt=$pdo->prepare('SELECT de.event_type review_result,de.detail review_comment,de.created_at reviewed_at,CONCAT(e.firstname," ",e.lastname) reviewer_name FROM document_events de LEFT JOIN employee e ON e.user_id=de.actor_user_id WHERE de.document_id=? AND de.event_type IN ("approved","revision_requested") ORDER BY de.created_at DESC,de.event_id DESC');$reviewStmt->execute([$documentId]);$reviews=$reviewStmt->fetchAll(PDO::FETCH_ASSOC);
$attachmentStmt=$pdo->prepare('SELECT attachment_id,original_name,file_size FROM document_attachments WHERE document_id=? ORDER BY uploaded_at');$attachmentStmt->execute([$documentId]);$attachments=$attachmentStmt->fetchAll(PDO::FETCH_ASSOC);
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="th"><head>
    <link rel="icon" type="image/png" href="/Project/assets/images/fet-logo-transparent.png?v=20260815-3">
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $fromCoordinator?'พิจารณาคำร้องสหกิจ':'พิจารณาคำร้อง' ?></title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"></head><body class="min-h-screen bg-gray-100 text-gray-900"><?php include 'sidebar.php'; ?><div class="min-h-screen lg:ml-72"><?php include 'navbar.php'; ?><main class="p-4 sm:p-6 lg:p-8"><a href="<?= $returnPage ?>" class="text-sm font-bold text-red-700"><i class="fa-solid fa-arrow-left mr-2"></i><?= $fromCoordinator?'กลับหน้าคำร้องสหกิจ — อาจารย์ประสานงาน':'กลับหน้าพิจารณาคำร้อง' ?></a><section class="mt-4 grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]"><div class="overflow-hidden rounded-xl border bg-white"><div class="border-b p-5"><span class="rounded-full bg-red-100 px-3 py-1 text-xs font-bold text-red-700"><?= h($document['document_code']) ?></span><?php if(!empty($document['workflow_step_name'])):?><span class="ml-2 rounded-full bg-blue-100 px-3 py-1 text-xs font-bold text-blue-700">ขั้นปัจจุบัน: <?=h($document['workflow_step_name'])?></span><?php endif;?><h1 class="mt-3 text-xl font-bold"><?= h($document['document_name']) ?></h1><p class="mt-1 text-sm text-gray-500"><?= h($document['student_number'].' '.$document['firstname'].' '.$document['lastname']) ?></p></div><div class="p-6 text-center"><i class="fa-solid fa-file-pdf text-6xl text-red-600"></i><p class="mt-3 text-sm text-gray-500">เปิด PDF เพื่อตรวจรายละเอียดก่อนบันทึกผล</p><a target="_blank" href="../student/download_document.php?document=<?= $documentId ?>" class="mt-4 inline-flex rounded-lg bg-gray-950 px-5 py-3 font-bold text-white"><i class="fa-solid fa-arrow-up-right-from-square mr-2"></i>เปิดเอกสาร PDF</a></div><div class="border-t p-5"><h2 class="font-bold">เอกสารแนบ</h2><?php if($attachments): ?><ul class="mt-3 divide-y"><?php foreach($attachments as $file): ?><li class="flex items-center justify-between gap-3 py-3 text-sm"><span class="truncate"><?= h($file['original_name']) ?></span><a href="../student/download_attachment.php?attachment=<?= (int)$file['attachment_id'] ?>" class="font-bold text-red-700">ดาวน์โหลด</a></li><?php endforeach; ?></ul><?php else: ?><p class="mt-2 text-sm text-gray-500">ไม่มีเอกสารแนบ</p><?php endif; ?></div></div><aside class="space-y-5"><form id="review-form" method="post" action="process_review.php" class="rounded-xl border bg-white p-5 shadow-sm"><?= csrf_field() ?><input type="hidden" name="document_id" value="<?= $documentId ?>"><input type="hidden" name="return_to" value="<?= $fromCoordinator?'coordinator':'' ?>"><h2 class="font-bold">ผลการพิจารณา<?= $fromCoordinator?'ของอาจารย์ประสานงาน':'' ?></h2><label class="mt-4 block text-sm font-bold">ความคิดเห็นหรือรายละเอียดที่ต้องแก้ไข</label><textarea name="review_comment" rows="6" class="mt-2 w-full rounded-lg border border-gray-300 p-3"></textarea><div class="mt-4 grid gap-2"><button name="review_result" value="approved" class="rounded-lg bg-emerald-600 px-4 py-3 font-bold text-white disabled:cursor-wait disabled:opacity-60"><i class="fa-solid fa-circle-check mr-2"></i>อนุมัติขั้นตอนนี้</button><button name="review_result" value="revision_requested" class="rounded-lg bg-red-700 px-4 py-3 font-bold text-white disabled:cursor-wait disabled:opacity-60"><i class="fa-solid fa-rotate-left mr-2"></i>ส่งกลับให้นักศึกษาแก้ไข</button></div></form><section class="rounded-xl border bg-white p-5"><h2 class="font-bold">ประวัติการพิจารณา</h2><?php if($reviews): ?><div class="mt-3 space-y-3"><?php foreach($reviews as $review): ?><article class="border-l-2 border-red-300 pl-3 text-sm"><strong><?= $review['review_result']==='approved'?'อนุมัติแล้ว':'ขอแก้ไข' ?></strong><p class="mt-1 text-gray-600"><?= h($review['review_comment']?:'-') ?></p><p class="mt-1 text-xs text-gray-400"><?= h($review['reviewer_name']?:'-') ?> · <?= h($review['reviewed_at']) ?></p></article><?php endforeach; ?></div><?php else: ?><p class="mt-2 text-sm text-gray-500">ยังไม่มีประวัติ</p><?php endif; ?></section></aside></section></main></div><script>document.getElementById('review-form')?.addEventListener('submit',()=>{setTimeout(()=>{document.querySelectorAll('#review-form button[name="review_result"]').forEach(button=>{button.disabled=true;button.innerHTML='<i class="fa-solid fa-spinner fa-spin mr-2"></i>กำลังบันทึก';});},0);});</script></body></html>
